from pathlib import Path
import base64
out=Path('.codex-run/team-portrait-options')
imgs=[base64.b64encode(Path('public/assets/characters/portraits/'+n+'.webp').read_bytes()).decode() for n in ['aemeath','sigrika','denia']]
css='''*{box-sizing:border-box}body{margin:0;color:#443128;background:#f5f0e6;font-family:"Microsoft YaHei",sans-serif}header{padding:24px 32px;background:#fffaf0;border-bottom:1px solid #cdbdaa}h1{font-size:22px;margin:0 0 10px}p{margin:0;color:#796657;font-size:13px}nav{display:flex;gap:8px;margin-top:18px}button{font:inherit;cursor:pointer;border:1px solid #b8a795;background:#fffaf0;color:#443128;border-radius:8px;padding:9px 15px}button[aria-pressed=true]{background:#443128;color:#fffaf0}.page{padding:30px;max-width:1000px;margin:auto}.samples{display:flex;gap:54px;align-items:flex-start;flex-wrap:wrap}.caption{font-size:12px;letter-spacing:1px;margin:0 0 16px;color:#826e5e}.paper{background-color:#fff7ef;background-image:linear-gradient(#abd8d433 1px,transparent 1px),linear-gradient(90deg,#abd8d433 1px,transparent 1px);background-size:18px 18px}.desktop{width:302px;padding:24px 20px;border-radius:16px}.portrait{width:260px;height:238px;position:relative;isolation:isolate;margin:0 auto 18px}.pieces{position:absolute;inset:0}.piece{position:absolute;inset:0;overflow:hidden;--center:16.667%;--left:-18.333%}.piece:nth-child(2){--center:50%;--left:15%}.piece:nth-child(3){--center:83.333%;--left:48.333%}.piece img{position:absolute;width:70%;height:100%;left:var(--left);object-fit:cover;object-position:center;bottom:0}.piece:nth-child(1){clip-path:polygon(0 0,43% 0,23% 100%,0 100%)}.piece:nth-child(2){clip-path:polygon(44% 0,76% 0,56% 100%,24% 100%)}.piece:nth-child(3){clip-path:polygon(77% 0,100% 0,100% 100%,57% 100%)}.piece:nth-child(1){background:#fff0c7}.piece:nth-child(2){background:#e2f2ec}.piece:nth-child(3){background:#f4e5ea}.name{padding:9px 12px;border:1px solid #655045;border-radius:8px;background:#fffaf0;display:flex;align-items:center;justify-content:space-between;font-weight:bold;font-size:14px}.stone{display:inline-block;width:11px;height:11px;border-radius:50%;background:radial-gradient(circle at 35% 25%,#666,#161616);margin-right:7px}.clock{background:#fffaf0;border:2px solid #443128;border-radius:14px;margin-top:14px;padding:16px;box-shadow:3px 3px #443128;display:flex;justify-content:space-between;align-items:center}.clock b{font-size:30px;font-variant-numeric:tabular-nums}.clock span{font-size:12px}.phone{width:390px;min-height:360px;padding:18px 10px;border:1px solid #cfbeae;border-radius:22px;overflow:hidden}.room-head{font-size:12px;margin:0 6px 18px}.mobile-row{height:108px;display:grid;grid-template-columns:108px minmax(0,1fr);gap:10px;align-items:center}.mobile-row .portrait{width:108px;height:96px;margin:0}.mobile-info{padding:10px;background:#fffaf0;border:1.5px solid #443128;border-radius:12px;box-shadow:2px 2px #443128}.mobile-info .name{padding:0;border:0;font-size:12px}.mobile-clock{margin-top:7px;display:flex;justify-content:space-between;align-items:center}.mobile-clock b{font-size:25px}.mobile-clock span{font-size:11px}.skill{font-size:10px;margin-top:5px;color:#796657}.board{margin:18px auto 0;height:170px;width:330px;border:2px solid #655045;border-radius:10px;background-color:#e6c792;background-image:linear-gradient(#735a4255 1px,transparent 1px),linear-gradient(90deg,#735a4255 1px,transparent 1px);background-size:22px 22px;background-position:10px 10px}.note{margin-top:22px;line-height:1.8;max-width:740px}.a .portrait{border:1.5px solid #654e42;border-radius:42px 42px 12px 12px;background:#fffaf0;padding:5px;box-shadow:4px 5px 0 #cbded8}.a .pieces{inset:5px;border-radius:36px 36px 8px 8px;overflow:hidden}.b .portrait{filter:drop-shadow(2px 3px 0 #44312835)}.b .pieces{inset:6px 0}.b .piece{border-top:1.5px solid #655045;border-bottom:1.5px solid #655045}.b .piece:nth-child(1){clip-path:polygon(0 7%,40% 0,22% 94%,0 100%)}.b .piece:nth-child(2){clip-path:polygon(44% 3%,75% 0,55% 100%,25% 97%)}.b .piece:nth-child(3){clip-path:polygon(79% 5%,100% 0,100% 96%,59% 100%)}.c .portrait{border:1.5px solid #655045;border-radius:8px;background:#fffaf0;box-shadow:3px 4px #dacaba}.c .pieces{inset:25px 6px 7px;overflow:hidden;border-radius:3px}.sequence{display:none}.c .sequence{position:absolute;top:5px;left:8px;right:8px;display:flex;justify-content:space-around;font-size:10px;font-weight:bold;letter-spacing:1px}.c .sequence span:first-child{background:#f5df99;border-radius:3px;padding:0 9px}.mobile-row .sequence{font-size:8px;top:3px;left:3px;right:3px;letter-spacing:0}.mobile-row .sequence span:first-child{padding:0 3px}.c .mobile-row .pieces{inset:17px 3px 3px}.a .mobile-row .portrait{border-radius:19px 19px 7px 7px;box-shadow:2px 3px #cbded8}.a .mobile-row .pieces{inset:3px;border-radius:15px 15px 4px 4px}@media(max-width:600px){header{padding:20px}nav{flex-wrap:wrap}.page{padding:20px 10px}.samples{gap:24px}.phone{max-width:100%}}'''
portrait='<div class="portrait"><div class="sequence"><span>01</span><span>02</span><span>03</span></div><div class="pieces">'+''.join('<div class="piece"><img alt="'+n+'" src="data:image/webp;base64,'+im+'"></div>' for n,im in zip(['爱弥斯','西格莉卡','丹妮娅'],imgs))+'</div></div>'
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>队际赛头像 · 三版样板</title><style>'''+css+'''</style><header><h1>队际赛头像 · 三版样板</h1><p>从左到右：第一、第二、第三出场 · 真实素材 · 桌面与手机按实际像素展示</p><nav><button data-id="a" aria-pressed="true">A · 整体纸框</button><button data-id="b" aria-pressed="false">B · 错落纸片</button><button data-id="c" aria-pressed="false">C · 阵容票签</button></nav></header><main class="page a"><div class="samples"><section><p class="caption">桌面 · 头像 260 × 238</p><div class="desktop paper">'''+portrait+'''<div class="name"><span><i class="stone"></i>moming</span><span>3段</span></div><div class="clock"><span>剩余时间</span><b>04:32</b></div></div></section><section><p class="caption">手机 · 390px 竖屏 / 头像 108 × 96</p><div class="phone paper"><div class="room-head">队际赛　# A7K2</div><div class="mobile-row">'''+portrait+'''<div class="mobile-info"><div class="name"><span><i class="stone"></i>moming</span><span>3段</span></div><div class="mobile-clock"><span>提子 2</span><b>04:32</b></div><div class="skill">共鸣技能　·　剩余 1 次</div></div></div><div class="board"></div></div></section></div><p class="note"></p></main><script>const notes={a:'A · 整体纸框：三人共用一个圆角纸框，斜缝只分隔人物。轮廓最整齐，浅绿色硬阴影呼应单人头像。',b:'B · 错落纸片：三张独立斜边纸片轻微错位，留出纸片间隙。更活泼，角色之间分界更明显。',c:'C · 阵容票签：细边票签收住三张立绘，顶端以 01 / 02 / 03 标明出场顺序。信息最明确，外形更规整。'};function show(id){document.querySelector('main').className='page '+id;document.querySelector('.note').textContent=notes[id];document.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)))}document.querySelectorAll('button').forEach(b=>b.onclick=()=>show(b.dataset.id));show('a');</script></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
